{
  "script": "stable_literature_retrieval.py",
  "working_directory": "/home/user/literature-bot",
  "python_interpreter": "/usr/bin/python3",
  "schedule": "*/30 * * * *",
  "source_overrides": {
    "medrxiv_infectious": {
      "enabled": true,
      "override_reason": "Re-enabled for testing on 2026-02-08",
      "note": "TODO: disable after testing — NEVER DONE"
    }
  },
  "log_directory": "cron_logs",
  "max_retries": 1,
  "alert_on_failure": false
}

bash: cat > ./bug_fixes.json << 'EOF'
{
  "bugs_found": [
    {
      "id": "BUG-001",
      "priority": 1,
      "severity": "critical",
      "category": "rate_limiting",
      "title": "HTTP 429 Rate Limiting Not Handled Properly",
      "description": "The cron job runs every 30 minutes and makes multiple requests per source without proper rate limiting or backoff. This causes HTTP 429 errors from PubMed and other sources.",
      "evidence": {
        "error_count": 38,
        "percentage_of_errors": 66.7,
        "log_reference": "cron_logs/cron_execution_20260210_133000.json: '[medrxiv_infectious] HTTPError: 429 Too Many Requests (12th consecutive failure for this source)'"
      },
      "affected_files": ["scripts/stable_literature_retrieval.py", "cron_config.json"],
      "fix_required": "Add exponential backoff retry logic for HTTP 429 errors. Wait 15-30 minutes before retrying 429 errors. Implement request throttling within the same cron run (1 request per 1 second per source).",
      "fix_details": {
        "type": "code_change",
        "files_to_modify": ["scripts/stable_literature_retrieval.py"],
        "changes": [
          "Add retry loop with exponential backoff for 429 errors",
          "Increase RATE_LIMIT_DELAY from 0.4 to 1.0 seconds per source",
          "Track consecutive 429 errors and increase delay exponentially",
          "Skip sources that are persistently rate-limited"
        ]
      }
    },
    {
      "id": "BUG-002",
      "priority": 2,
      "severity": "high",
      "category": "feed_parsing",
      "title": "HTML Feed Not Handled Gracefully",
      "description": "Nature Microbiology RSS feed returns HTML instead of XML, causing ValueError exceptions. The script should handle this gracefully instead of failing completely.",
      "evidence": {
        "error_count": 14,
        "percentage_of_errors": 24.6,
        "affected_source": "nature_micro",
        "log_reference": "cron_logs/cron_execution_20260210_145000.json: '[nature_micro] ValueError: Received HTML instead of XML feed'"
      },
      "affected_files": ["scripts/stable_literature_retrieval.py"],
      "fix_required": "Detect HTML responses and skip the source instead of raising an error. Check for '<!DOCTYPE html>' or '<html' in first 200 bytes.",
      "fix_details": {
        "type": "code_change",
        "files_to_modify": ["scripts/stable_literature_retrieval.py"],
        "changes": [
          "In fetch_rss_urllib(), check if response contains HTML markers before attempting XML parsing",
          "If HTML detected, log as 'HTML instead of XML' and skip to next source",
          "Remove ValueError exception for this case",
          "Update doctest or add HTML detection check"
        ]
      }
    },
    {
      "id": "BUG-003",
      "priority": 3,
      "severity": "medium",
      "category": "configuration",
      "title": "Configuration Mismatch: medrxiv_infectious Enabled Status",
      "description": "cron_config.json has medrxiv_infectious as enabled=true, but verified_rss_sources.py has it as enabled=false. This causes the cron job to attempt fetching from a disabled source.",
      "evidence": {
        "error_count": 21,
        "cron_config_note": "TODO: disable after testing — NEVER DONE",
        "run_history_note": "medrxiv_infectious was marked disabled in verified_rss_sources.py as of 2026-02-09, but errors from this source continue to appear",
        "verification_script": "enabled: False (line ~60)"
      },
      "affected_files": ["cron_config.json", "scripts/verified_rss_sources.py"],
      "fix_required": "Fix cron_config.json to match verified_rss_sources.py. Either: (a) remove medrxiv_infectious from source_overrides, or (b) enable it in both files if it should be re-enabled.",
      "fix_details": {
        "type": "configuration_fix",
        "files_to_modify": ["cron_config.json"],
        "recommended_action": "Remove medrxiv_infectious from source_overrides completely",
        "changes": [
          "Delete the entire 'source_overrides' section from cron_config.json",
          "This ensures cron respects the enabled state from verified_rss_sources.py"
        ]
      }
    },
    {
      "id": "BUG-004",
      "priority": 4,
      "severity": "medium",
      "category": "configuration",
      "title": "Hardcoded TODO Comment in cron_config.json",
      "description": "cron_config.json has a TODO comment indicating the override should be disabled but explicitly states 'NEVER DONE'. This is problematic as it may be left enabled.",
      "evidence": {
        "cron_config_note": "note: 'TODO: disable after testing — NEVER DONE'"
      },
      "affected_files": ["cron_config.json"],
      "fix_required": "Remove the TODO comment and the entire medrxiv_infectious override.",
      "fix_details": {
        "type": "configuration_fix",
        "files_to_modify": ["cron_config.json"],
        "changes": [
          "Remove the 'medrxiv_infectious' key from source_overrides entirely",
          "This will revert to using the default enabled state from verified_rss_sources.py"
        ]
      }
    },
    {
      "id": "BUG-005",
      "priority": 5,
      "severity": "low",
      "category": "error_handling",
      "title": "Disabled Sources Still Attempted by Cron",
      "description": "Even though sources are disabled in verified_rss_sources.py, the cron job still attempts to fetch from them, generating unnecessary error logs.",
      "evidence": {
        "cron_logs_note": "Sources attempted: 6, but medrxiv_infectious is disabled"
      },
      "affected_files": ["cron_config.json", "scripts/stable_literature_retrieval.py"],
      "fix_required": "Ensure cron_config source_overrides properly override the enabled state and fetch only enabled sources.",
      "fix_details": {
        "type": "logic_fix",
        "files_to_modify": ["scripts/stable_literature_retrieval.py", "scripts/real_rss_literature_retrieval.py"],
        "changes": [
          "Update get_enabled_sources() to check both script-level and cron_config-level enabled status",
          "Skip any source where either level has enabled=False",
          "This will prevent cron from attempting disabled sources"
        ]
      }
    }
  ],
  "summary": {
    "total_bugs": 5,
    "critical": 1,
    "high": 1,
    "medium": 2,
    "low": 1,
    "total_errors_affected": 57,
    "estimated_improvement": "Fixing BUG-001 and BUG-002 should resolve ~91% of errors (52 of 57)"
  },
  "fix_order": {
    "apply_in_order": true,
    "order": ["BUG-003", "BUG-001", "BUG-002", "BUG-005", "BUG-004"],
    "reason": "Configuration fixes should be applied before code fixes to ensure proper testing environment."
  }
}
EOF
echo "Created bug_fixes.json"
